//! OpenAPI 3.1 description of the HTTP API (M0-10).
//!
//! The endpoint table below is the source; `GET /api/v1/openapi.json` serves
//! the document built from it, and `data/openapi/openapi.json` is a checked-in
//! copy for the docs site and other tools. Tests keep all three honest: every
//! route the router registers must be in the table and vice versa, and the
//! checked-in copy must match what the code builds.
//!
//! Request bodies that are core spec types reuse their JSON Schemas
//! (schemars); the web client's types stay generated by ts-rs.

use std::sync::Arc;

use axum::routing::get;
use axum::{Json, Router};
use serde_json::{Map, Value, json};

use crate::api::App;

/// Paths under `/api/v1` unless they start with `/ws/`.
pub const API_PREFIX: &str = "/api/v1";

/// One operation: method, path (axum syntax, `{param}`), tag, summary and
/// the request body schema, if any.
pub struct Op {
    pub method: &'static str,
    pub path: &'static str,
    pub tag: &'static str,
    pub summary: &'static str,
    pub body: Option<&'static str>,
}

const fn op(
    method: &'static str,
    path: &'static str,
    tag: &'static str,
    summary: &'static str,
) -> Op {
    Op {
        method,
        path,
        tag,
        summary,
        body: None,
    }
}

const fn with_body(
    method: &'static str,
    path: &'static str,
    tag: &'static str,
    summary: &'static str,
    body: &'static str,
) -> Op {
    Op {
        method,
        path,
        tag,
        summary,
        body: Some(body),
    }
}

