/// The full URL path of an operation.
pub fn full_path(o: &Op) -> String {
    if o.path.starts_with("/ws/") {
        o.path.to_string()
    } else {
        format!("{API_PREFIX}{}", o.path)
    }
}

fn params(path: &str) -> Vec<Value> {
    path.split('/')
        .filter_map(|s| s.strip_prefix('{')?.strip_suffix('}'))
        .map(|name| {
            json!({
                "name": name,
                "in": "path",
                "required": true,
                "schema": { "type": "string" }
            })
        })
        .collect()
}

/// Move a schemars document's `$defs` into `schemas` and point its refs there.
fn hoist(name: &str, mut schema: Value, schemas: &mut Map<String, Value>) {
    if let Some(Value::Object(defs)) = schema.as_object_mut().and_then(|o| o.remove("$defs")) {
        for (k, v) in defs {
            schemas.insert(k, v);
        }
    }
    if let Some(o) = schema.as_object_mut() {
        o.remove("$schema");
    }
    schemas.insert(name.into(), schema);
}

fn rewrite_refs(v: &mut Value) {
    match v {
        Value::Object(o) => {
            if let Some(Value::String(r)) = o.get_mut("$ref")
                && let Some(rest) = r.strip_prefix("#/$defs/")
            {
                *r = format!("#/components/schemas/{rest}");
            }
            o.values_mut().for_each(rewrite_refs);
        }
        Value::Array(a) => a.iter_mut().for_each(rewrite_refs),
        _ => {}
    }
}

fn schemas() -> Map<String, Value> {
    let mut s = Map::new();
    hoist("VmSpec", qemu_ui_core::spec::json_schema(), &mut s);
    hoist(
        "NetworkConfig",
        serde_json::to_value(schemars::schema_for!(qemu_ui_core::network::NetworkConfig))
            .unwrap_or_default(),
        &mut s,
    );
    s.insert(
        "SpecBody".into(),
        json!({
            "type": "object",
            "required": ["spec"],
            "properties": { "spec": { "$ref": "#/components/schemas/VmSpec" } }
        }),
    );
    s.insert(
        "CompileBody".into(),
        json!({
            "type": "object",
            "required": ["spec"],
            "properties": {
                "spec": { "$ref": "#/components/schemas/VmSpec" },
                "vm_id": { "type": ["string", "null"] }
            }
        }),
    );
    s.insert(
        "NetworkBody".into(),
        json!({
            "type": "object",
            "required": ["name", "config"],
            "properties": {
                "name": { "type": "string" },
                "config": { "$ref": "#/components/schemas/NetworkConfig" }
            }
        }),
    );
    s.insert(
        "Error".into(),
        json!({
            "type": "object",
            "required": ["error"],
            "properties": { "error": { "type": "string" } }
        }),
    );
    let mut v = Value::Object(s);
    rewrite_refs(&mut v);
    match v {
        Value::Object(s) => s,
        _ => unreachable!(),
    }
}

/// The OpenAPI document.
pub fn document() -> Value {
    let mut paths = Map::new();
    for o in OPS {
        let mut operation = json!({
            "tags": [o.tag],
            "summary": o.summary,
            "operationId": format!("{}{}", o.method, o.path.replace(['{', '}'], "").replace(['/', '-', '.'], "_")),
            "responses": {
                "default": {
                    "description": "On failure, a JSON error",
                    "content": { "application/json": { "schema": { "$ref": "#/components/schemas/Error" } } }
                },
                "2XX": { "description": "Success" }
            }
        });
        let ps = params(o.path);
        if !ps.is_empty() {
            operation["parameters"] = Value::Array(ps);
        }
        if let Some(b) = o.body {
            operation["requestBody"] = json!({
                "required": true,
                "content": { "application/json": { "schema": { "$ref": format!("#/components/schemas/{b}") } } }
            });
        }
        let entry = paths
            .entry(full_path(o))
            .or_insert_with(|| Value::Object(Map::new()));
        entry[o.method] = operation;
    }
    json!({
        "openapi": "3.1.0",
        "info": {
            "title": "qemu-ui API",
            "version": env!("CARGO_PKG_VERSION"),
            "description": "HTTP API of qemu-uid. Browsers authenticate with a session cookie and send X-CSRF-Token on unsafe methods; other clients send an API token as a Bearer token. WebSocket routes need a single-use ticket from the ticket endpoint."
        },
        "components": {
            "schemas": schemas(),
            "securitySchemes": {
                "token": { "type": "http", "scheme": "bearer" },
                "session": { "type": "apiKey", "in": "cookie", "name": "qui_session" }
            }
        },
        "security": [ { "token": [] }, { "session": [] } ],
        "paths": paths
    })
}

pub fn routes() -> Router<Arc<App>> {
    Router::new().route("/openapi.json", get(|| async { Json(document()) }))
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::BTreeSet;
    use std::path::Path;

    /// `(method, path)` for every `.route("…", get(…).post(…))` in `src`,
    /// skipping `#[cfg(test)]` modules and test-only files.
    fn source_routes(src: &str) -> Vec<(String, String)> {
        let src = match src.find("#[cfg(test)]\nmod ") {
            Some(i) => &src[..i],
            None => src,
        };
        let b = src.as_bytes();
        let mut out = Vec::new();
        let mut i = 0;
        while let Some(off) = src[i..].find(".route(") {
            let start = i + off + ".route(".len();
            let mut j = start;
            while b[j].is_ascii_whitespace() {
                j += 1;
            }
            i = start;
            if b[j] != b'"' {
                continue;
            }
            let end = j + 1 + src[j + 1..].find('"').unwrap();
            let path = &src[j + 1..end];
            // The handler expression runs to the `)` closing `.route(`.
            let mut depth = 1;
            let mut k = end + 1;
            while depth > 0 {
                match b[k] {
                    b'(' => depth += 1,
                    b')' => depth -= 1,
                    _ => {}
                }
                k += 1;
            }
            let handlers = &src[end + 1..k];
            for m in ["get", "post", "put", "delete", "patch"] {
                let mut s = 0;
                while let Some(p) = handlers[s..].find(&format!("{m}(")) {
                    let at = s + p;
                    let before = handlers[..at].chars().last().unwrap_or(' ');
                    if !(before.is_alphanumeric() || before == '_') {
                        out.push((m.to_string(), path.to_string()));
                    }
                    s = at + m.len();
                }
            }
            i = k;
        }
        out
    }

    fn all_source_routes() -> BTreeSet<(String, String)> {
        let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("src");
        let mut files = vec![];
        let mut stack = vec![root];
        while let Some(d) = stack.pop() {
            for e in std::fs::read_dir(d).unwrap() {
                let p = e.unwrap().path();
                if p.is_dir() {
                    stack.push(p);
                } else if p.extension().is_some_and(|x| x == "rs")
                    && !p.file_stem().unwrap().to_string_lossy().ends_with("_test")
                {
                    files.push(p);
                }
            }
        }
        files
            .iter()
            .flat_map(|f| {
                let s = std::fs::read_to_string(f).unwrap().replace("\r\n", "\n");
                source_routes(&s)
            })
            .collect()
    }

    #[test]
    fn extractor_reads_multi_line_routes_and_skips_tests() {
        let src = "Router::new()\n    .route(\n        \"/a/{x}\",\n        get(h).put(u),\n    )\n    .route(\"/b\", post(nested(f(1))))\n#[cfg(test)]\nmod t { fn f() { r.route(\"/t\", get(x)); } }";
        assert_eq!(
            source_routes(src),
            [("get", "/a/{x}"), ("put", "/a/{x}"), ("post", "/b")]
                .map(|(m, p)| (m.to_string(), p.to_string()))
        );
    }

    #[test]
    fn every_route_is_documented_and_every_documented_route_exists() {
        let code = all_source_routes();
        let doc: BTreeSet<_> = OPS
            .iter()
            .map(|o| (o.method.to_string(), o.path.to_string()))
            .collect();
        let missing: Vec<_> = code.difference(&doc).collect();
        let stale: Vec<_> = doc.difference(&code).collect();
        assert!(
            missing.is_empty() && stale.is_empty(),
            "OpenAPI table out of date.\n  routes not in openapi.rs OPS: {missing:?}\n  OPS entries with no route: {stale:?}"
        );
        assert_eq!(doc.len(), OPS.len(), "duplicate entries in OPS");
    }

    #[test]
    fn document_refs_resolve() {
        let doc = document();
        let schemas = doc["components"]["schemas"].as_object().unwrap();
        let mut refs = vec![];
        fn walk(v: &Value, out: &mut Vec<String>) {
            match v {
                Value::Object(o) => {
                    if let Some(Value::String(r)) = o.get("$ref") {
                        out.push(r.clone());
                    }
                    o.values().for_each(|v| walk(v, out));
                }
                Value::Array(a) => a.iter().for_each(|v| walk(v, out)),
                _ => {}
            }
        }
        walk(&doc, &mut refs);
        assert!(!refs.is_empty());
        for r in refs {
            let name = r
                .strip_prefix("#/components/schemas/")
                .unwrap_or_else(|| panic!("unexpected ref {r}"));
            assert!(schemas.contains_key(name), "dangling ref {r}");
        }
    }

    /// `data/openapi/openapi.json` must match the code. Regenerate with
    /// `UPDATE_GOLDEN=1 cargo test -p qemu-ui-daemon openapi`.
    #[test]
    fn checked_in_document_is_current() {
        let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../data/openapi/openapi.json");
        let actual = serde_json::to_string_pretty(&document()).unwrap() + "\n";
        if std::env::var_os("UPDATE_GOLDEN").is_some() {
            std::fs::create_dir_all(path.parent().unwrap()).unwrap();
            std::fs::write(&path, &actual).unwrap();
            return;
        }
        let expected = std::fs::read_to_string(&path)
            .unwrap_or_default()
            .replace("\r\n", "\n");
        assert!(
            actual == expected,
            "stale data/openapi/openapi.json; run with UPDATE_GOLDEN=1"
        );
    }
}
